"""Public responsive reference. Artwork is resolved by the shared art manifest at runtime."""
from pathlib import Path
import json,re
from website_content import ROOT,finish
from site_policy import decorate
def build():
 data=json.loads((ROOT/'regeln/flottenausbau.json').read_text(encoding='utf-8'))
 factions=json.loads((ROOT/'content/catalog.json').read_text(encoding='utf-8'))['factions'];data['factions']=factions
 public_rules=json.loads((ROOT/'content/public-game-catalog.json').read_text(encoding='utf-8'))
 source=(ROOT/'regeln/online-v1.ron').read_text(encoding='utf-8').split('voelker:',1)[1].split('wirtschaft:',1)[0]
 for key,f in factions.items():
  body=(re.search(r'\b'+key+r':\s*\((.*?)\)',source,re.S) or [None,''])[1]
  f['values']={k:float(v) for k,v in re.findall(r'\b(ladung|waffen|panzerung|kolonieschiff):\s*([0-9.]+)',body)}
 doc='''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sternenepoche · Flottenkodex</title><meta name="description" content="Alle vier Völker, 27 Schiffstypen je Volk, ihre Aufgaben, Konter, Voraussetzungen und drei Planetenschildstufen."><!-- SITE_THEME --><style>html{scroll-padding-top:0}
body{background:#050b13;color:#edf5fc}.codex-wrap{max-width:1280px;margin:auto;padding:20px clamp(12px,3vw,36px) 60px}.codex-head{display:flex;align-items:center;justify-content:space-between;gap:14px}.codex-head a{color:#dcf5ff}.codex-intro{max-width:850px;line-height:1.65;color:#c6d7e4}.codex-intro h1{color:#f7e5b6;font-size:clamp(1.55rem,4vw,2.6rem);line-height:1.15}.codex-filter{display:grid;grid-template-columns:1fr 1fr 1.4fr;gap:12px;margin:22px 0}.codex-filter label{display:grid;gap:7px;font-size:.82rem;color:#cee4f5}.codex-filter select,.codex-filter input{background:#102033;color:white;border:1px solid #4c637b;min-height:44px;border-radius:9px;padding:8px;width:100%;box-sizing:border-box}.codex-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.9fr);gap:24px;align-items:start}.codex-detail{border:1px solid #476278;border-radius:18px;overflow:hidden;background:linear-gradient(125deg,#102336ec,#091724ed);scroll-margin-top:16px}.codex-art{width:100%;height:clamp(180px,27vw,360px);object-fit:contain;background:radial-gradient(ellipse at center,#20354b55,#030811)}.codex-copy{padding:clamp(14px,2vw,26px)}.codex-copy h2{margin:0 0 9px;color:#fff0ca}.codex-copy p{color:#d4e2ed;line-height:1.55}.codex-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.codex-facts div{background:#0b1727a6;border:1px solid #334e68;border-radius:10px;padding:10px}.codex-facts dt{font-size:.74rem;color:#bacee0}.codex-facts dd{margin:5px 0 0;color:#fff1c9;font-weight:700}.codex-copy h3{font-size:.95rem;color:#fff1c9}.codex-copy ul{padding-left:20px;color:#d4e2ed;line-height:1.75}.codex-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.codex-tile{min-width:0;border:1px solid #34506a;border-radius:12px;overflow:hidden;background:#0e2134c9;color:#f1f7fe;text-align:left;padding:0;cursor:pointer;min-height:44px}.codex-tile[aria-pressed=true]{border-color:#92dfff;box-shadow:inset 0 0 0 1px #92dfff}.codex-tile img{width:100%;height:100px;object-fit:contain;background:#050c16}.codex-tile span{display:block;padding:9px;font-size:.85rem;line-height:1.35}.codex-pending{min-height:120px;display:grid;place-content:center;background:linear-gradient(135deg,#172c4050,#061321);color:#c9e8fb;font-size:.82rem;padding:12px}.codex-preview-note{border-left:3px solid #99dbf7;padding:10px 14px;color:#d2e8f6;background:#17324b55;border-radius:6px}.codex-tile:focus-visible,a:focus-visible{outline:3px solid #adeaff;outline-offset:3px}
@media(max-width:700px){.codex-layout{grid-template-columns:minmax(0,1fr)}.codex-filter{grid-template-columns:1fr 1fr}.codex-filter label:last-child{grid-column:1/-1}.codex-gallery{grid-template-columns:repeat(3,minmax(0,1fr))}.codex-tile img{height:80px}.codex-tile span{font-size:.72rem;padding:8px}.codex-pending{min-height:80px}.codex-wrap{padding-top:14px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media(forced-colors:active){.codex-detail,.codex-facts div,.codex-tile{border:1px solid CanvasText}}
</style><script src="web-client/art.js"></script><script src="web-client/technology-rules.js"></script><link rel="stylesheet" href="web-client/public-techtree.css"></head><body><main class="codex-wrap"><header class="codex-head"><a href="index.html">⌂ Sternenepoche</a><a href="Sternenepoche-Start.html">Spielguide</a><a href="web-client/">Zum Spiel</a></header><div class="codex-intro"><h1>Deine Flotte. Dein Plan.</h1><p>27 Schiffstypen je Volk: vier Jäger, vier Transporter, vier Kreuzer, vier Schlachter, zwei Bomber, drei Zerstörer und zwei Kolonieschiffe – ergänzt um Sonde, Bergbau, Bergung und Truppentransport. Fünf Verteidigungswaffen und drei Planetenschildstufen schützen deine Welten.</p><p class="codex-preview-note">Die neue Fassung wird vorbereitet. Dieser Kodex zeigt die abgestimmten Steckbriefe. Eigene Forschungsstufen, laufende Bauzeiten und tatsächlich verfügbare Ressourcen findest du im Spiel. Noch fehlende Motive sind ausdrücklich gekennzeichnet.</p></div><form class="codex-filter" onsubmit="return false"><label>Volk<select id="faction"></select></label><label>Klasse<select id="class"><option value="">Alle Klassen</option></select></label><label>Direktauswahl<select id="unit"></select></label><label>Suchen<input id="search" type="search" placeholder="Name, Aufgabe oder Konter"></label></form><div class="codex-layout"><section id="detail" class="codex-detail" aria-live="polite"></section><section><p id="result-count"></p><div id="gallery" class="codex-gallery" aria-label="Einheiten auswählen"></div></section></div></main><script id="fleet-data" type="application/json">DATA</script><script>
const data=JSON.parse(document.getElementById('fleet-data').textContent),el=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n||0).toLocaleString('de-DE',{maximumFractionDigits:1}),names=window.STERNEN_ART?.names||{},name=k=>names[k]||data.units[k]?.label||k.replaceAll('_',' ');let chosen='leichter_jaeger';
const classes={jaeger:'Jäger',transporter:'Transporter',kreuzer:'Kreuzer',schlachter:'Schlachter',bomber:'Bomber',zerstoerer:'Zerstörer',kolonie:'Kolonieschiffe',sonde:'Sonden',bergbau:'Bergbau',bergung:'Recycler',truppen:'Truppentransport',verteidigung:'Verteidigungswaffen',schild:'Planetenschilde'};
el('faction').innerHTML=Object.entries(data.factions).map(([k,f])=>`<option value="${k}">${esc(f.label)}</option>`).join('');el('class').insertAdjacentHTML('beforeend',Object.entries(classes).map(([k,v])=>`<option value="${k}">${v}</option>`).join(''));
function picture(key,large=false){const u=data.units[key],cat=['verteidigung','schild'].includes(u.klasse)?'defenses':'ships',a=window.STERNEN_ART?.images?.[`${cat}|${key}|${el('faction').value}`];return a?`<img class="${large?'codex-art':''}" src="web-client/${esc(a.url)}" alt="${esc(name(key)+' · '+data.factions[el('faction').value].label)}" ${large?'':'loading="lazy"'}>`:`<div class="codex-pending${large?' codex-art':''}"><span>✧ ${esc(name(key))}<br>Volksmotiv wird ergänzt</span></div>`;}
function render(){const faction=el('faction').value,f=data.factions[faction],query=el('search').value.toLocaleLowerCase('de'),entries=Object.entries(data.units).filter(([k,u])=>(!el('class').value||u.klasse===el('class').value)&&(!query||(name(k)+' '+data.profiles[k].rolle+' '+Object.keys(data.profiles[k].schadensfaktoren).map(name).join(' ')).toLocaleLowerCase('de').includes(query)));
 if(!entries.some(([k])=>k===chosen))chosen=entries[0]?.[0];el('unit').innerHTML=entries.map(([k])=>`<option value="${k}" ${chosen===k?'selected':''}>${esc(name(k))}</option>`).join('');el('result-count').textContent=entries.length+' Einträge · '+f.label;
 el('gallery').innerHTML=entries.map(([k,u])=>`<button class="codex-tile" type="button" data-unit="${k}" aria-pressed="${chosen===k}">${picture(k)}<span>${esc(name(k))}</span></button>`).join('');if(!chosen){el('detail').innerHTML='<div class="codex-copy">Keine passenden Einheiten.</div>';return;}
 const u=data.units[chosen],p=data.profiles[chosen],v=f.values||{},cost=Object.fromEntries(Object.entries(u.kosten).map(([k,n])=>[k,p.klasse==='kolonie'?Math.floor(n*(v.kolonieschiff||1)):n]));
 const fact=(k,n)=>`<div><dt>${k}</dt><dd>${fmt(n)}</dd></div>`;
 el('detail').innerHTML=picture(chosen,true)+`<div class="codex-copy"><small>${esc(f.label)} · ${esc(classes[u.klasse])}</small><h2>${esc(name(chosen))}</h2><p>${esc(p.rolle)}</p><dl class="codex-facts">${fact('Angriff',Math.floor(u.angriff*(v.waffen||1)))}${fact('Schild',u.schild)}${fact('Struktur',Math.floor(u.struktur*(v.panzerung||1)))}${fact('Tempo',u.tempo)}${fact('Fracht',Math.floor(u.ladung*(v.ladung||1)))}${fact('Treibstoff',u.verbrauch)}${fact('Besatzung',u.besatzung)}${fact('Getrennte Ziele',p.ziele)}${fact('Zivilisationsstufe',u.ab_stufe)}</dl><p>Grundwerte mit Volksbonus; deine Forschung verbessert sie zusätzlich. Treibstoffkosten ergeben sich aus Strecke, Tempo und Raumhafen.</p><h3>Voraussetzungen</h3><ul><li>Zivilisationsstufe ${u.ab_stufe}</li>${u.werft?`<li>Werft ${u.werft}</li>`:''}${Object.entries(u.braucht).map(([k,n])=>`<li>${esc(name(k))} ${n}</li>`).join('')}${Object.entries(p.voraussetzungen).map(([k,n])=>`<li>${esc(name(k))} ${n}</li>`).join('')}</ul><h3>Kosten</h3><p>${Object.entries(cost).map(([k,n])=>`${esc(name(k))} ${fmt(n)}`).join(' · ')}</p><h3>Konter und Nachteile</h3><ul>${Object.entries(p.schadensfaktoren).map(([k,n])=>`<li>${esc(name(k))}: Schaden ×${fmt(n)}</li>`).join('')||'<li>Grundschaden; Eskorte für zivile Schiffe einplanen.</li>'}</ul>${p.schildfaktor!==1?`<p>Schildschaden ×${fmt(p.schildfaktor)}.</p>`:''}${p.siedler?`<h3>Koloniestart</h3><p>${fmt(p.siedler)} eingeschiffte Siedler · ${p.kolonie_minen} fertige Minen · Grundversorgung und mindestens ${fmt(u.ladung)} Rohstoff-Lagerkapazität. Ein Kolonieschiff wird bei Gründung verbraucht.</p>`:''}${p.klasse==='schild'?'<p>Pro Planet eine aktive Schildstufe. Eine höhere Stufe ersetzt das kleinere System.</p>':''}<h3>Schnellfeuer</h3><p>${Object.entries(u.schnellfeuer).map(([k,n])=>`${esc(name(k))} ×${n}`).join(' · ')||'Keines'} · Folgeschüsse auf dasselbe Ziel; maximal 64. Mehrzielwaffen wählen bis zu vier verschiedene Ziele je Runde.</p></div>`;
}
el('gallery').addEventListener('click',e=>{const b=e.target.closest('[data-unit]');if(!b)return;chosen=b.dataset.unit;render();window.PublicTechnologyTree?.select((['verteidigung','schild'].includes(data.units[chosen].klasse)?'defenses:':'ships:')+chosen);el('detail').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});});el('unit').onchange=()=>{chosen=el('unit').value;render();window.PublicTechnologyTree?.select((['verteidigung','schild'].includes(data.units[chosen].klasse)?'defenses:':'ships:')+chosen);};for(const id of ['faction','class','search'])el(id).addEventListener(id==='search'?'input':'change',render);render();
</script></body></html>'''.replace('PUBLIC_RULES',json.dumps(public_rules,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')).replace('DATA',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c'))
 tree='''<section class="public-tech-section" aria-labelledby="tree-title"><h2 id="tree-title">Dein Weg zum nächsten Ziel</h2><p>Wähle eine Forschung, ein Schiff, eine Verteidigung, ein Gebäude oder eine Zivilisationsstufe. Die Pfade zeigen die tatsächlichen Voraussetzungen von links nach rechts; die Zahl am Pfad ist die benötigte Stufe. Auf dem Handy kannst du den Baum innerhalb dieses Fensters verschieben. Öffne „Alle Bedingungen“ für Kosten und weitere Anforderungen.</p><label>Ziel planen<select id="tree-goal"></select></label><div id="public-tree" class="public-tree" tabindex="0" aria-label="Voraussetzungsbaum, horizontal und vertikal scrollbar"></div></section>'''
 doc=doc.replace('</main>',tree+'</main>',1).replace('</body>','<script id="public-rules" type="application/json">'+json.dumps(public_rules,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')+'</script><script src="web-client/public-techtree.js"></script></body>',1)
 doc=doc.replace('<form class="codex-filter" onsubmit="return false">','<div class="codex-filter">').replace('</form>','</div>')
 target=ROOT/'Sternenepoche-Kodex.html';target.write_text(decorate(finish(doc),'KI-Hinweis.html'),encoding='utf-8');print('Erstellt: '+str(target))
if __name__=='__main__':build()
